import os
import tempfile
from pathlib import Path

import pytest

from envcfg import EnvCfgError, load_envcfg


def _mk_env(prefix="", **kwargs):
    env = dict(os.environ)
    for k, v in kwargs.items():
        env[f"{prefix}__{k.upper()}"] = str(v)
    return env


def _write_toml(path, data):
    with open(path, "wb") as f:
        import tomllib
        # Write a minimal TOML file manually (tomllib only reads, not writes)
        f.write(tomllib.dumps(data).encode())


def test_defaults_only():
    cfg = load_envcfg({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_overrides_defaults():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        path = Path(f.name)
        _write_toml(path, {"a": 10, "c": 3})
    try:
        cfg = load_envcfg({"a": 1, "b": 2}, toml_path=str(path))
        assert cfg == {"a": 10, "b": 2, "c": 3}
    finally:
        path.unlink()


