    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        path = Path(f.name)
        _write_toml(path, {"a": 10, "b": 20})
    try:
        cfg = load_envcfg({"a": 1, "b": 2}, toml_path=str(path), env_map=_mk_env("APP", a=100, b=200))
        assert cfg == {"a": 100, "b": 200}
