import os
import tempfile
from pathlib import Path

import pytest

from envcfg import EnvCfgError, load_envcfg


def _clean_env(**kwargs):
    """Return a dict of env vars, ignoring everything else."""
    return {k: str(v) for k, v in kwargs.items()}


def _write_toml(path, data):
    """Write a TOML file manually (tomllib only reads)."""
    with open(path, "w", encoding="utf-8") as f:
        f.write("# auto-generated TOML\n")
        for k, v in data.items():
            if isinstance(v, dict):
                f.write(f"[{k}]\n")
                for kk, vv in v.items():
                    f.write(f"  {kk} = {toml_value(vv)}\n")
            else:
                f.write(f"{k} = {toml_value(v)}\n")


def toml_value(v):
    """Convert a Python value to TOML string."""
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (int, float)):
        return str(v)
    if isinstance(v, str):
        return f'"{v}"'
    raise ValueError(f"Unsupported type for TOML: {type(v)}")


